242	     */
243	    public Pet getPet(String name, boolean ignoreNew) {
244	        name = name.toLowerCase();
245	        for (Pet pet : getPetsInternal()) {
246	            if (!ignoreNew || !pet.isNew()) {
247	                String compName = pet.getName();
