17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
38	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
39	import org.springframework.samples.petclinic.rest.controller.HouseholdResolver;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.samples.petclinic.util.HashUtils;
49	import org.springframework.samples.petclinic.util.IdentityUtils;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
73	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
74	
75	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
76	     *  these (case-insensitively) is refused with 400. */
77	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
78	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
79	
80	    /** Dedicated audit logger; emits an audit line on successful owner create. */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    private final TelephoneNormalizer telephoneNormalizer;
92	
93	    private final AddressNormalizer addressNormalizer;
94	
95	    private final CityRegionResolver cityRegionResolver;
96	
97	    private final HouseholdResolver householdResolver;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper,
103	                                 TelephoneNormalizer telephoneNormalizer,
104	                                 AddressNormalizer addressNormalizer,
105	                                 CityRegionResolver cityRegionResolver,
106	                                 HouseholdResolver householdResolver) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	        this.telephoneNormalizer = telephoneNormalizer;
112	        this.addressNormalizer = addressNormalizer;
113	        this.cityRegionResolver = cityRegionResolver;
114	        this.householdResolver = householdResolver;
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
120	        Collection<Owner> owners;
121	        if (lastName != null) {
122	            owners = this.clinicService.findOwnerByLastName(lastName);
123	        } else {
124	            owners = this.clinicService.findAllOwners();
125	        }
126	        if (owners.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        if (owner.getRegistrationDate() == null) {
148	            owner.setRegistrationDate(LocalDate.now());
149	        }
150	        // A supplied registration date may not be later than the server's current date.
151	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
155	        LocalDate registrationDate = owner.getRegistrationDate();
156	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
157	            .map(Owner::getRegistrationDate)
158	            .filter(registrationDate::equals)
159	            .count();
160	        if (ownersCreatedThatDay >= 100) {
161	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
162	        }
163	        String address = normalizedAddress(owner);
164	        if (address == null) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        owner.setAddress(address);
168	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
169	        if (telephone == null) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        owner.setTelephone(telephone);
176	        String email = owner.getEmail();
177	        if (email != null) {
178	            email = email.trim();
179	            if (!EMAIL_PATTERN.matcher(email).matches()) {
180	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	            }
182	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
183	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
184	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	            }
186	            owner.setEmail(email.toLowerCase(Locale.ROOT));
187	        }
188	        // A postcode is optional, but when supplied it must be four digits and valid for the
189	        // owner's city per the fixed region table; a city with no known region accepts any
190	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
191	        String postcode = owner.getPostcode();
192	        if (postcode != null) {
193	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
194	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
195	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	            }
197	        }
198	        // The owner's telephone and email are now in their canonical, stored form.
199	        // The household id is deterministic: owners with the same normalized last name and
200	        // postcode share it automatically. Assign it unconditionally before the duplicate
201	        // checks so both the household-duplicate rule and the identity-key rule key off the
202	        // same computed id.
203	        owner.setHouseholdId(householdResolver.householdId(owner));
204	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
205	        boolean householdMember = householdResolver.householdExists(owner);
206	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
207	        // existing owner's household is a household duplicate and is rejected with 409. The
208	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
209	        // no longer creates the link, which the deterministic id now does on its own.
210	        if (householdMember && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        if (isDuplicateOwner(owner)) {
214	            return new ResponseEntity<>(HttpStatus.CONFLICT);
215	        }
216	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
217	        long ownersInCity = this.clinicService.findAllOwners().stream()
218	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
219	            .count();
220	        if (ownersInCity >= 50) {
221	            return new ResponseEntity<>(HttpStatus.CONFLICT);
222	        }
223	        owner.setCustomerCode(customerCode(owner));
224	        owner.setNamesakeCount(namesakeCount(owner));
225	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
226	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
227	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
228	        // still share an existing owner's last name and postcode while carrying a different
229	        // telephone. When it does, it is created but flagged as a possible duplicate of that
230	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
231	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
232	        // is never flagged.
233	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
234	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
235	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
236	        this.clinicService.saveOwner(owner);
237	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
238	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
239	            ownerMapper.membershipLevel(owner), owner.getMembershipNumber());
240	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
241	        headers.setLocation(UriComponentsBuilder.newInstance()
242	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
243	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
244	    }
245	
246	    /**
247	     * The owner's postal address in the single canonical form under which it is stored, or
248	     * {@code null} when the owner supplies no usable address. The raw address is reduced to its
249	     * canonical form by {@link AddressNormalizer}; a blank result (a missing or whitespace-only
250	     * address) has no canonical form and is reported as {@code null} so the caller can reject the
251	     * request with 400.
252	     *
253	     * <p>This is the single point at which an owner's address is resolved and normalized on
254	     * create, so every rule keyed on the stored address reads the one value produced here.
255	     *
256	     * @param owner the owner about to be created
257	     * @return the canonical stored address, or {@code null} when the owner supplies none
258	     */
259	    private String normalizedAddress(Owner owner) {
260	        String address = addressNormalizer.normalize(owner.getAddress());
261	        return address.isBlank() ? null : address;
262	    }
263	
264	    /**
265	     * Whether {@code candidate} collides with an already-registered owner under the single
266	     * identity rule enforced on create. This is the one point at which a new owner is
267	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
268	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
269	     * email (or an empty string when absent) and the householdId joined by '|'. The
270	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
271	     * the telephone is part of the key, two members of the same household (same householdId)
272	     * with different telephones have different identityKeys and are both allowed.
273	     *
274	     * <p>The candidate arrives with its telephone and email already normalized and its
275	     * household id already derived, and each existing owner is stored in the same canonical
276	     * form, so an identityKey match means the two owners are genuinely the same identity.
277	     *
278	     * @param candidate the fully-normalized owner about to be created
279	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
280	     */
281	    private boolean isDuplicateOwner(Owner candidate) {
282	        String identityKey = OwnerMapper.identityKey(candidate);
283	        return this.clinicService.findAllOwners().stream()
284	            .map(OwnerMapper::identityKey)
285	            .anyMatch(identityKey::equals);
286	    }
287	
288	    /**
289	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
290	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
291	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
292	     * postcode while carrying a different telephone — a likely re-registration of the same
293	     * person under a new number. Both must supply a postcode for a match to be possible; when
294	     * several existing owners qualify the lowest id is returned so the result is deterministic.
295	     *
296	     * @param candidate the fully-normalized owner about to be created
297	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
298	     */
299	    private Integer possibleDuplicateOf(Owner candidate) {
300	        String postcode = candidate.getPostcode();
301	        if (postcode == null) {
302	            return null;
303	        }
304	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
305	        return this.clinicService.findAllOwners().stream()
306	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
307	                && postcode.equals(existing.getPostcode())
308	                && !postcode.isBlank()
309	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
310	            .map(Owner::getId)
311	            .filter(java.util.Objects::nonNull)
312	            .min(Integer::compareTo)
313	            .orElse(null);
314	    }
315	
316	    /**
317	     * Build the customer code assigned to {@code owner} on create, formatted
318	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
319	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
320	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
321	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
322	     *
323	     * <p>When the computed code collides with an already-registered owner's customerCode it is
324	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
325	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
326	     */
327	    private String customerCode(Owner owner) {
328	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
329	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
330	        String base = region + "-" + hash8;
331	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
332	            .map(Owner::getCustomerCode)
333	            .filter(java.util.Objects::nonNull)
334	            .collect(java.util.stream.Collectors.toSet());
335	        if (!existing.contains(base)) {
336	            return base;
337	        }
338	        int n = 2;
339	        while (existing.contains(base + "-" + n)) {
340	            n++;
341	        }
342	        return base + "-" + n;
343	    }
344	
345	    /**
346	     * The number of existing owners that share {@code owner}'s firstName and lastName,
347	     * compared case-insensitively. The candidate is not yet stored at the point this is
348	     * assigned, so it does not count itself. This is the value stored as the owner's
349	     * namesakeCount on create.
350	     */
351	    private int namesakeCount(Owner owner) {
352	        return (int) this.clinicService.findAllOwners().stream()
353	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
354	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
355	            .count();
356	    }
357	
358	    /**
359	     * Roll a registration date forward to the next business day: a Saturday or Sunday
360	     * advances to the following Monday, and a weekday is returned unchanged.
361	     */
362	    private static LocalDate toBusinessDay(LocalDate date) {
363	        return switch (date.getDayOfWeek()) {
364	            case SATURDAY -> date.plusDays(2);
365	            case SUNDAY -> date.plusDays(1);
366	            default -> date;
367	        };
368	    }
369	
370	    /**
371	     * Build the membership number assigned on create, formatted
372	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
373	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
374	     */
375	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
376	        String yy = String.format("%02d", registrationDate.getYear() % 100);
377	        return customerCode + "-M" + yy;
378	    }
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Override
382	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
383	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
384	        if (currentOwner == null) {
385	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
386	        }
387	        currentOwner.setAddress(ownerFieldsDto.getAddress());
388	        currentOwner.setCity(ownerFieldsDto.getCity());
389	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
390	        currentOwner.setLastName(ownerFieldsDto.getLastName());
391	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
392	        this.clinicService.saveOwner(currentOwner);
393	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
394	    }
395	
396	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
397	    @Transactional
398	    @Override
399	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
400	        Owner owner = this.clinicService.findOwnerById(ownerId);
401	        if (owner == null) {
402	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
403	        }
404	        this.clinicService.deleteOwner(owner);
405	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
406	    }
407	
408	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
409	    @Override
410	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
411	        Owner owner = this.clinicService.findOwnerById(ownerId);
412	        if (owner == null) {
413	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
414	        }
415	        HttpHeaders headers = new HttpHeaders();
416	        Pet pet = petMapper.toPet(petFieldsDto);
417	        owner.setId(ownerId);
418	        pet.setOwner(owner);
419	        pet.getType().setName(null);
420	        this.clinicService.savePet(pet);
421	        PetDto petDto = petMapper.toPetDto(pet);
422	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
423	            .buildAndExpand(pet.getId()).toUri());
424	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
425	    }
426	
427	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
428	    @Override
429	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
430	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
431	        if (currentOwner != null) {
432	            Pet currentPet = this.clinicService.findPetById(petId);
433	            if (currentPet != null) {
434	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
435	                currentPet.setName(petFieldsDto.getName());
436	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
437	                this.clinicService.savePet(currentPet);
438	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
439	            }
440	        }
441	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
442	    }
443	
444	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
445	    @Override
446	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
447	        HttpHeaders headers = new HttpHeaders();
448	        Visit visit = visitMapper.toVisit(visitFieldsDto);
449	        Pet pet = new Pet();
450	        pet.setId(petId);
451	        visit.setPet(pet);
452	        this.clinicService.saveVisit(visit);
453	        VisitDto visitDto = visitMapper.toVisitDto(visit);
454	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
455	            .buildAndExpand(visit.getId()).toUri());
456	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
457	    }
458	
459	
